import sys
from collections import defaultdict

def solve():
    data = sys.stdin.buffer.read().split()
    idx = 0
    T = int(data[idx]); idx += 1
    out = []
    for _ in range(T):
        N = int(data[idx]); idx += 1
        L = 2 * N
        A = data[idx:idx+L]
        # Convert to ints
        A = [int(x) for x in A]
        idx += L

        groups = defaultdict(list)
        for i in range(L - 1):
            x = A[i]
            y = A[i+1]
            if x != y:
                if x < y:
                    key = (x, y)
                else:
                    key = (y, x)
                groups[key].append(i)

        ans = 0
        for lst in groups.values():
            k = len(lst)
            if k < 2:
                continue
            for a in range(k):
                ia = lst[a]
                for b in range(a+1, k):
                    jb = lst[b]
                    d = jb - ia
                    if d == 1:
                        continue
                    elif d == 2:
                        if A[ia] == A[jb]:
                            ans += 1
                    else:  # d >= 3
                        ans += 1

        out.append(str(ans))

    sys.stdout.write('\n'.join(out) + '\n')

